# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(9 * 60 + 5, 17 * 60 + 12)]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [Span(8, 68)]
        self.assertEqual(
            round_spans(spans, 15), ["00:15-01:15 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        spans = [Span(60, 120)]
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_spans(spans, step)
